const $=id=>document.getElementById(id);let calls=[],editing=null,loading=false;
function render(){
 $('total').textContent=calls.length;$('answered').textContent=calls.filter(c=>c.result==='Answered').length;$('unanswered').textContent=calls.filter(c=>c.result==='Not answered').length;
 const query=$('search').value.toLowerCase();const rows=calls.filter(c=>(!$('type').value||c.type===$('type').value)&&(!$('result').value||c.result===$('result').value)&&(c.name+' '+c.phone).toLowerCase().includes(query));$('calls').replaceChildren();
 for(const call of rows){const tr=document.createElement('tr'),date=new Date(call.date);for(const text of [date.toLocaleDateString(),date.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'}),call.type+(call.source==='browser'?' · Website':''),call.phone||'—',call.name||'—',call.duration==null?'—':Math.floor(call.duration/60)+':'+String(call.duration%60).padStart(2,'0'),call.result,call.remarks||'—']){const td=document.createElement('td');td.textContent=text;tr.append(td)}const recordingCell=document.createElement('td');if(call.recordingId){const play=document.createElement('button');play.className='quiet';play.textContent='▶ Play recording';play.onclick=()=>openRecording(call);recordingCell.append(play)}else recordingCell.textContent='Not available';tr.append(recordingCell);const td=document.createElement('td'),button=document.createElement('button');button.textContent='Edit';button.className='quiet';button.setAttribute('aria-label','Edit call to '+call.phone);button.onclick=()=>{editing=call.id;$('remarks').value=call.remarks||'';$('editResult').value='';$('editStatus').textContent='';$('editDialog').showModal()};td.append(button);tr.append(td);$('calls').append(tr)}
 $('historyStatus').textContent=rows.length?`${rows.length} call${rows.length===1?'':'s'} shown`:(calls.length?'No calls match these filters.':'No calls recorded yet. Your next phone calls will appear here.');
}
async function load(){if(loading)return;loading=true;$('refresh').disabled=true;try{const r=await fetch('api/call-history');if(r.status===401){location.replace('login');return}if(!r.ok)throw Error();calls=(await r.json()).calls;render()}catch{$('historyStatus').textContent='Could not load call history. Click Refresh to retry.'}finally{loading=false;$('refresh').disabled=false}}
$('refresh').onclick=load;for(const id of ['search','type','result'])$(id).addEventListener('input',render);
$('cancelEdit').onclick=()=>$('editDialog').close();
$('editForm').onsubmit=async e=>{e.preventDefault();$('saveEdit').disabled=true;try{const r=await fetch('api/call-history',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:editing,remarks:$('remarks').value,result:$('editResult').value})});if(!r.ok)throw Error();$('editDialog').close();await load()}catch{$('editStatus').textContent='Could not save. Please retry.'}finally{$('saveEdit').disabled=false}};
load();setInterval(()=>{if(!document.hidden&&!$('editDialog').open)load()},15000);

function openRecording(call){$('recordingDetails').textContent=(call.name||call.phone)+' · '+new Date(call.date).toLocaleString();$('recordingStatus').textContent='';const audio=$('recordingAudio');audio.src='api/call-recording?id='+encodeURIComponent(call.id);$('recordingDialog').showModal();audio.play().catch(()=>{$('recordingStatus').textContent='Press play to listen. If playback fails, refresh the dashboard and try again.'})}
$('closeRecording').onclick=()=>$('recordingDialog').close();
$('recordingDialog').addEventListener('close',()=>{const audio=$('recordingAudio');audio.pause();audio.removeAttribute('src');audio.load()});
$('recordingAudio').addEventListener('error',()=>{if($('recordingAudio').hasAttribute('src'))$('recordingStatus').textContent='Recording could not be loaded. Sign in again or refresh and retry.'});
window.addEventListener('pagehide',()=>$('recordingAudio').pause());

const sidebarLogout=document.getElementById('logout');
if(sidebarLogout)sidebarLogout.onclick=async()=>{sidebarLogout.disabled=true;try{const r=await fetch('api/auth/logout',{method:'POST'});if(!r.ok)throw Error();location.replace('login')}catch{document.getElementById('logoutStatus').textContent='Could not sign out. Please try again.';sidebarLogout.disabled=false}};
